select.where:

    and p.product_code like concat('%', #{productCode}, '%')


    and p.product_name like concat('%', #{productName}, '%')


    and p.category_name like concat('%', #{categoryName}, '%')


    and p.brand_name like concat('%', #{brandName}, '%')


    and p.bar_code = #{barCode}


    and p.status = #{status}


    and p.del_flag = #{delFlag}

${params.dataScope}

mapper.update:
update md_product
product_code = #{productCode}, product_name = #{productName}, product_spec = #{productSpec}, unit_name = #{unitName}, bar_code = #{barCode}, category_name = #{categoryName}, brand_name = #{brandName}, product_image = #{productImage}, cost_price = #{costPrice}, sale_price = #{salePrice}, status = #{status}, del_flag = #{delFlag}, update_by = #{updateBy}, update_time = sysdate(), remark = #{remark},
where product_id = #{productId}
